<?php namespace App\Models; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Database\Eloquent\Relations\HasOne; use Illuminate\Database\Eloquent\SoftDeletes; class Sale extends Model { use HasFactory,SoftDeletes; protected $fillable=['customer_name','phone','address','sale_date','subtotal','discount','delivery_fee','total_amount','payment_method','payment_status','user_id']; protected function casts():array{return ['sale_date'=>'date','subtotal'=>'decimal:2','discount'=>'decimal:2','delivery_fee'=>'decimal:2','total_amount'=>'decimal:2'];} public function items():HasMany{return $this->hasMany(SaleItem::class);} public function invoice():HasOne{return $this->hasOne(Invoice::class);} public function user():BelongsTo{return $this->belongsTo(User::class);} }